insert into public.dd_governed_service_offers(id,master_record_id,canonical_sku,service_name,division,commercial_object_type,runtime_service_id,pricing_rule_count,market_rule_count,channel_availability_count,authorized_provider_capability_count,priced_channel_count,ch01_a_priced,ch01_b_priced,commercial_offer_status,fulfillment_gate_status,offer_basis,source_authority,created_at,updated_at)
select v.id::uuid,v.master_record_id::uuid,v.canonical_sku,v.service_name,v.division,v.commercial_object_type,s.id,v.pricing_rule_count,v.market_rule_count,v.channel_availability_count,v.authorized_provider_capability_count,v.priced_channel_count,v.ch01_a_priced,v.ch01_b_priced,v.commercial_offer_status,v.fulfillment_gate_status,v.offer_basis,v.source_authority,v.created_at::timestamptz,v.updated_at::timestamptz from v join public.services s on s.sku=v.canonical_sku
where not exists(select 1 from public.dd_governed_service_offers o where o.canonical_sku=v.canonical_sku);